"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"life","metadata":{"permalink":"/blog/life","source":"@site/blog/2024-11-21-academic-life/index.md","title":"Academic Life","description":"Hi, I\'m Zoe","date":"2024-11-21T00:00:00.000Z","tags":[],"readingTime":0.8,"hasTruncateMarker":true,"authors":[{"name":"Zoe","title":"ML Engineer, Data Scientist","url":"https://eztechstudios.com","page":{"permalink":"/blog/authors/zoe"},"socials":{"github":"https://github.com/zoelesv","linkedin":"https://www.linkedin.com/in/zoelesv/","x":"https://x.com/zoe_le_"},"imageURL":"https://github.com/zoelesv.png","key":"zoe"}],"frontMatter":{"slug":"life","title":"Academic Life","authors":["zoe"],"tags":[],"comments":true},"unlisted":false,"nextItem":{"title":"Welcome","permalink":"/blog/welcome"}},"content":"Hi, I\'m Zoe\\n\\nWelcome to my journal. Reflecting on my academic journey, I\u2019ve noticed a recurring pattern of deep learning every five years. \\n\x3c!-- truncate --\x3e\\nFrom ages 7 to 12, I focused on competitive math. I was very proud to get some money reward every single year from doing this. \\nAfterward, as soon as I was introduced to Physics, I loved it. I spent the first year simply getting acquainted with the subject. That led to five years of competitive physics from ages 13 to 18, during which I was part of a gifted class in high school.\\n\\nHowever, pursuing a career in science wasn\u2019t encouraged in Vietnam where I grew up, so I didn\u2019t continue in that field. I also came to realize that life is much more than theory.\\n\\nNow, as I work in data science, I find myself looking back on everything I\u2019ve done that has led me to this point and how it all connects."},{"id":"welcome","metadata":{"permalink":"/blog/welcome","source":"@site/blog/2021-08-26-welcome/index.md","title":"Welcome","description":"Hi, I\'m Zoe","date":"2021-08-26T00:00:00.000Z","tags":[{"inline":false,"label":"Hello","permalink":"/blog/tags/hello","description":"Hello tag description"}],"readingTime":1.1,"hasTruncateMarker":true,"authors":[{"name":"Zoe","title":"ML Engineer, Data Scientist","url":"https://eztechstudios.com","page":{"permalink":"/blog/authors/zoe"},"socials":{"github":"https://github.com/zoelesv","linkedin":"https://www.linkedin.com/in/zoelesv/","x":"https://x.com/zoe_le_"},"imageURL":"https://github.com/zoelesv.png","key":"zoe"}],"frontMatter":{"slug":"welcome","title":"Welcome","authors":["zoe"],"tags":["hello"],"comments":true},"unlisted":false,"prevItem":{"title":"Academic Life","permalink":"/blog/life"}},"content":"Hi, I\'m Zoe\\n\\nWelcome to my blog! If you don\'t know me. You can learn more about my journey here.\\n\x3c!-- truncate --\x3e\\n\\nI\u2019m an AI Engineer with a Master in Data Science from USF.\\n\\nBefore diving into Data Science, I worked for a leading resort chain in Phu Quoc, Vietnam, where I carried out business analysis. I found myself fascinated with data patterns and proposed ideas to improve the business through statistical reports. During my time there, the company earned 9 World Travel Awards.\\nWhen the pandemic hit, I was lucky to shelter in Silicon Valley. I was selected as a section leader for Stanford\u2019s Code in Place, covering half of the CS106A \ud83c\udf32. This was a dream come true and my favorite in terms of learning and teaching experience with Python.\\nSince then, I\u2019ve worked as a machine learning engineer, developing models, and creating visualizations across multiple industries such as e-commerce, education, and travel. (Check out my projects \ud83d\udc40)\\nI\'m passionate about learning and seeking new challenges!\\n\\nMy favourite Shakespeare\'s quote: \\"To be, or not to be\\" \ud83c\udf3f My motto: Love Live Laugh, Touch Grass.\\n\\nI do my work with passion. Outside of machine learning and data science, I spend my time gardening, playing sports with friends, traveling, and enjoying having a good laugh.\\n\\nGreat things are coming!"}]}}')}}]);